using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public class TicketInput
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string Category { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];
}

namespace TicketClassifier.Models;

public record PredictRequest(string Subject, string Description, int Priority);

public record PredictResponse(string Category, Dictionary<string, float> Confidence);

public record EvaluationResponse(
    double MacroAccuracy,
    double MicroAccuracy,
    double LogLoss,
    double LogLossReduction,
    IReadOnlyList<PerClassMetric> PerClassMetrics);

public record PerClassMetric(string Class, double Precision, double Recall, double F1Score);

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly PredictionEngine<TicketInput, TicketPrediction> _predictionEngine;
    private readonly EvaluationResponse _evaluationMetrics;
    private readonly string[] _classLabels;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 42);

        var dataView = _mlContext.Data.LoadFromTextFile<TicketInput>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        // Combine text features and build the pipeline
        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketInput.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketInput.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketInput.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .AppendCacheCheckpoint(_mlContext)
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        var model = pipeline.Fit(dataView);

        // Extract ordered class labels from the trained model's key-value mapping
        var transformer = model.LastTransformer.Previous!.Previous!; // MapValueToKey step
        VBuffer<ReadOnlyMemory<char>> keyValues = default;
        transformer.GetOutputSchema(dataView.Schema)["Label"]
            .GetKeyValues(ref keyValues);
        _classLabels = keyValues.DenseValues().Select(v => v.ToString()).ToArray();

        // Evaluate with cross-validation on the small dataset
        var cvResults = _mlContext.MulticlassClassification
            .CrossValidate(dataView, pipeline, numberOfFolds: 3, labelColumnName: "Label");

        var best = cvResults.OrderByDescending(r => r.Metrics.MacroAccuracy).First();
        var m = best.Metrics;

        var perClass = new List<PerClassMetric>();
        for (int i = 0; i < m.PerClassLogLoss.Count && i < _classLabels.Length; i++)
        {
            perClass.Add(new PerClassMetric(
                _classLabels[i],
                Precision: double.IsNaN(m.ConfusionMatrix.PerClassPrecision[i]) ? 0 : m.ConfusionMatrix.PerClassPrecision[i],
                Recall: double.IsNaN(m.ConfusionMatrix.PerClassRecall[i]) ? 0 : m.ConfusionMatrix.PerClassRecall[i],
                F1Score: ComputeF1(m.ConfusionMatrix.PerClassPrecision[i], m.ConfusionMatrix.PerClassRecall[i])));
        }

        _evaluationMetrics = new EvaluationResponse(
            m.MacroAccuracy, m.MicroAccuracy, m.LogLoss, m.LogLossReduction, perClass);

        _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketInput, TicketPrediction>(model);
    }

    public PredictResponse Predict(PredictRequest request)
    {
        var input = new TicketInput
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(input);

        var confidence = new Dictionary<string, float>();
        for (int i = 0; i < prediction.Score.Length && i < _classLabels.Length; i++)
        {
            confidence[_classLabels[i]] = prediction.Score[i];
        }

        return new PredictResponse(prediction.Category, confidence);
    }

    public EvaluationResponse GetMetrics() => _evaluationMetrics;

    private static double ComputeF1(double precision, double recall)
    {
        if (double.IsNaN(precision) || double.IsNaN(recall) || (precision + recall) == 0)
            return 0;
        return 2 * precision * recall / (precision + recall);
    }
}

using Microsoft.AspNetCore.Mvc;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketController : ControllerBase
{
    private readonly TicketClassifierService _classifier;

    public TicketController(TicketClassifierService classifier) => _classifier = classifier;

    /// <summary>Predict the category for a support ticket.</summary>
    [HttpPost("predict")]
    public ActionResult<PredictResponse> Predict([FromBody] PredictRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Subject) || string.IsNullOrWhiteSpace(request.Description))
            return BadRequest("Subject and Description are required.");

        if (request.Priority is < 1 or > 3)
            return BadRequest("Priority must be between 1 and 3.");

        return Ok(_classifier.Predict(request));
    }

    /// <summary>Return model evaluation metrics.</summary>
    [HttpGet("metrics")]
    public ActionResult<EvaluationResponse> Metrics() => Ok(_classifier.GetMetrics());
}

